import React from 'react';

const QuestionItem = ({
    question,
    numbering,
    onUpdate,
    onDelete,
    onAddChild,
}) => {
    return (
        <div className="border rounded-lg p-4 mb-4 bg-gray-50">
            <h2 className="font-bold mb-3 text-lg">{numbering}</h2>

            <div className="grid md:grid-cols-2 gap-4">
                <input
                    type="text"
                    placeholder="Enter Question"
                    value={question.text}
                    onChange={(e) =>
                        onUpdate(question.id, { text: e.target.value })
                    }
                    className="border p-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
                />

                <select
                    value={question.type}
                    onChange={(e) =>
                        onUpdate(question.id, {
                            type: e.target.value,
                            answer: '',
                        })
                    }
                    className="border p-2 rounded focus:outline-none focus:ring-2 focus:ring-blue-400"
                >
                    <option>Short Answer</option>
                    <option>True/False</option>
                </select>
            </div>

            {question.type === 'True/False' && (
                <div className="mt-4">
                    <label className="mr-3 font-medium">Answer:</label>

                    <select
                        value={question.answer}
                        onChange={(e) =>
                            onUpdate(question.id, {
                                answer: e.target.value,
                            })
                        }
                        className="border p-2 rounded"
                    >
                        <option value="">Select</option>
                        <option value="True">True</option>
                        <option value="False">False</option>
                    </select>
                </div>
            )}

            <div className="flex gap-3 mt-4 flex-wrap">
                {question.type === 'True/False' &&
                    question.answer === 'True' && (
                        <button
                            onClick={() => onAddChild(question.id)}
                            className="bg-purple-500 hover:bg-purple-600 text-white px-3 py-2 rounded"
                        >
                            Add Child Question
                        </button>
                    )}

                <button
                    onClick={() => onDelete(question.id)}
                    className="bg-red-500 hover:bg-red-600 text-white px-3 py-2 rounded"
                >
                    Delete
                </button>
            </div>

            {question.children.length > 0 && (
                <div className="ml-8 mt-4 border-l-4 pl-4 border-blue-300">
                    {question.children.map((child, index) => (
                        <QuestionItem
                            key={child.id}
                            question={child}
                            numbering={`${numbering}.${index + 1}`}
                            onUpdate={onUpdate}
                            onDelete={onDelete}
                            onAddChild={onAddChild}
                        />
                    ))}
                </div>
            )}
        </div>
    );
};

export default QuestionItem;
